mapper.select:
SELECT id, city, source_type AS sourceType, contribution_rate AS contributionRate, date, create_time AS createTime
FROM pollution_source


        AND city LIKE CONCAT('%', #{dto.city}, '%')


        AND source_type = #{dto.sourceType}


        AND date >= #{dto.startDate}


        AND date <= #{dto.endDate}


ORDER BY date DESC, contribution_rate DESC

SELECT source_type AS name, AVG(contribution_rate) AS value
FROM pollution_source


        AND city = #{city}


        AND date >= #{startDate}


        AND date <= #{endDate}


GROUP BY source_type
ORDER BY value DESC

SELECT source_type AS name, AVG(contribution_rate) AS value
FROM pollution_source


        AND date >= #{startDate}


        AND date <= #{endDate}


GROUP BY source_type
ORDER BY value DESC

SELECT DATE_FORMAT(date, '%Y-%m-%d') AS date, contribution_rate AS contributionRate
FROM pollution_source
WHERE city = #{city}
AND source_type = #{sourceType}
ORDER BY date DESC
LIMIT #{days}

SELECT city, contribution_rate AS contributionRate
FROM pollution_source
WHERE source_type = #{sourceType}
AND date = #{date}
AND city IN

    #{city}

ORDER BY contribution_rate DESC

SELECT id, city, source_type AS sourceType, contribution_rate AS contributionRate, date, create_time AS createTime
FROM pollution_source
WHERE date = (SELECT MAX(date) FROM pollution_source)

    AND city = #{city}

ORDER BY contribution_rate DESC
LIMIT #{limit}

SELECT
    period_value AS period,
    source_type AS sourceType,
    avg_contribution_rate AS avgContributionRate
FROM source_trend_data
WHERE city = #{city}
AND period_type = #{period}

    AND period_value >= #{startDate}


    AND period_value <= #{endDate}

ORDER BY period_value ASC, source_type ASC

SELECT
    city,
    ROUND(AVG(contribution_rate), 2) AS contributionRate,
    source_type AS sourceType
FROM pollution_source


        AND source_type = #{sourceType}


        AND date >= #{startDate}


        AND date <= #{endDate}


GROUP BY city, source_type
ORDER BY contributionRate DESC
LIMIT #{limit}

SELECT city, source_type AS sourceType, ROUND(AVG(contribution_rate), 2) AS contributionRate FROM pollution_source WHERE city IN
#{city}
AND date >= #{startDate}
AND date <= #{endDate}
GROUP BY city, source_type ORDER BY city, source_type
